function dimBadge(val) {
  if (val === null || val === undefined || val === 'null') return `<span class="dim-score dim-null">—</span>`;
  const n = parseFloat(val);
  if (isNaN(n)) return `<span class="dim-score dim-null">—</span>`;
  const cls = n >= 4 ? 'dim-high' : n >= 3 ? 'dim-mid' : 'dim-low';
  return `<span class="dim-score ${cls}">${n}</span>`;
}

