// Helper: extract LinkedIn job id from an object/json that may have job_id, job_url, or link
function extractIdFromJson(j) {
  if (!j) return null;
  if (j.job_id != null) return String(j.job_id);
  const url = String(j.job_url || j.link || '');
  const m = url.match(/-(\d{6,})(?:[/?#].*)?$/); // last hyphen-number at end
  return m ? m[1] : null;
}

