const overall = $input.first().json;

// Veto: preferences_rating = 0
const prefRating = $('Extract Preferences Response').item.json.preferences_rating;
if (prefRating === 0 || prefRating === '0') {
  return [{
    json: {
      ...overall,
      overall_score: 0.0,
      weights_used: {},
      dimensions_included: [],
      dimensions_excluded: ['all'],
      dimension_values: {},
      note: 'Veto: preferences_rating is 0 (on-site or hybrid role)'
    }
  }];
}

// Updated weights: skills_alignment bumped to 0.20, employee_satisfaction reduced to 0.25
const BASE_WEIGHTS = {
  employee_satisfaction: 0.25,
  salary_competitiveness: 0.25,
  remote_work_flexibility: 0.20,
  skills_alignment: 0.20,
  cultural_fit: 0.10,
};

const DIMENSIONS = [
  'employee_satisfaction',
  'salary_competitiveness',
  'remote_work_flexibility',
  'skills_alignment',
  'cultural_fit',
];

const present = {};
const missing = [];

for (const dim of DIMENSIONS) {
  const val = overall[dim];
  if (val !== null && val !== undefined && typeof val === 'number' && !isNaN(val)) {
    present[dim] = Math.max(1, Math.min(5, val));
  } else {
    missing.push(dim);
  }
}

const presentKeys = Object.keys(present);

if (presentKeys.length === 0) {
  return [{
    json: {
      ...overall,
      overall_score: 0.0,
      weights_used: {},
      dimensions_included: [],
      dimensions_excluded: DIMENSIONS,
      dimension_values: {},
      note: 'No valid dimension scores provided'
    }
  }];
}

// Renormalize weights across present dimensions
const rawWeightSum = presentKeys.reduce((s, k) => s + BASE_WEIGHTS[k], 0);
const normalizedWeights = {};
for (const key of presentKeys) {
  normalizedWeights[key] = BASE_WEIGHTS[key] / rawWeightSum;
}

// Compute weighted score
let weightedSum = 0;
for (const key of presentKeys) {
  weightedSum += present[key] * normalizedWeights[key];
}

const overallScore = Math.round(weightedSum * 10) / 10;

return [{
  json: {
    ...overall,
    overall_score: overallScore,
    weights_used: Object.fromEntries(
      Object.entries(normalizedWeights).map(([k, v]) => [k, Math.round(v * 1000) / 1000])
    ),
    dimensions_included: presentKeys,
    dimensions_excluded: missing,
    dimension_values: present,
    note: missing.length > 0
      ? `Weights renormalized. Excluded: ${missing.join(', ')}`
      : 'All dimensions present. Updated weights applied (25/25/20/20/10).'
  }
}];
